import sys; sys.path.insert(0,'/tmp/ss-build/tools/c10')
from engh import *
S='english'; FP='Footprints without Feet'
def L(*a): lesson(S,'fp',FP,*a)
L(1,"A Triumph of Surgery",("The dog who ate too much","A rich lady loved her little dog so much that she nearly made him ill. How did the vet help?"),
 [("The story is by James Herriot, a veterinary surgeon. He tells of Tricki Woo, a small Pekingese dog owned by the wealthy Mrs Pumphrey.","Herriot and Tricki"),
  ("Mrs Pumphrey pampered Tricki with too many rich foods and sweets, so he grew fat, lazy and breathless.","overfeeding"),
  ("She called the doctor in a state of panic, thinking Tricki was very ill, and begged him to save the dog.","Mrs Pumphrey's worry"),
  ("Herriot saw at once that Tricki was only overweight and lacked exercise. He decided the only way was to take Tricki away from her house.","the diagnosis"),
  ("He took Tricki to his own surgery, with Mrs Pumphrey and the staff weeping and throwing coats at the car.","taking Tricki away"),
  ("At Herriot's place Tricki was put on a strict diet and played with other dogs, so he became lean and lively.","diet and play"),
  ("After a few days he went home healthy, and Mrs Pumphrey called it a triumph of surgery, though no surgery was done.","the title's humour"),
  ("The story shows that love without sense can harm a pet, and that good care means the right food and exercise.","message")],
 ("Tricki weighed 9 kg and lost 2 kg. What is his new weight?",[("Subtract the loss from the weight.","9 - 2."),("= 7 kg.","Practice figures only.")]),
 ("Explain how love can be misplaced, using Tricki as an example.",["Overfeeding harms him","A diet and exercise cure him","The title is humorous"],["Thinking Tricki needed an operation"]),
 ["Tricki was ill because of overfeeding.","Herriot treated him with diet and exercise.","The title is humorous.","Care means sense as well as love."],
 [M("fp1-1",1,"Who is the narrator of the story?","James Herriot","Mrs Pumphrey","Tricki","He is a vet."),
  tf("fp1-2",1,"Tricki was a Pekingese dog.",True,"He belonged to Mrs Pumphrey."),
  M("fp1-3",2,"What was Tricki's problem?","He was overfed and lazy","He had a broken leg","He had a fever","The vet found no real disease."),
  AR("fp1-4",2,"Mrs Pumphrey called it a triumph of surgery.","No surgery was needed; a diet cured Tricki.","She did not understand the cure."),
  short("fp1-5",2,"Who owned Tricki?",["mrs pumphrey"],"A wealthy lady.",[("herriot","Herriot was the vet.")]),
  tf("fp1-6",3,"Tricki recovered by playing with other dogs and eating less.",True,"This was the cure."),
  M("fp1-7",3,"The tone of the story is","humorous","tragic","angry","It is light and comic."),
  M("fp1-8",3,"Herriot's profession is","veterinary surgeon","teacher","soldier","He treats animals.")])
L(2,"The Thief's Story",("The thief who learned to read","A young thief meets a trusting man. Does the thief betray him?"),
 [("The story is by Ruskin Bond. The narrator is Hari Singh, a fifteen-year-old thief who is experienced and fairly successful.","Hari Singh"),
  ("He meets Anil, about twenty-five, watching a wrestling match. Anil seems easy-going, kind and simple.","meeting Anil"),
  ("Hari tells a made-up story, and Anil takes him in as a cook and gives him food and a place.","Anil trusts him"),
  ("Anil is a struggling writer. He trusts Hari so much that he lets him look after his things, which makes the theft difficult.","a trusting man"),
  ("When Anil sells a story and keeps money in his room, Hari decides to steal it and catch the express train to Lucknow.","the plan"),
  ("Hari takes the notes at night but then thinks of Anil's trust and of learning to read and write, which would make him a clever and respected man.","change of mind"),
  ("He goes back and quietly slips the notes under the mattress while Anil sleeps.","returning the notes"),
  ("Next morning Anil says he made some money and will now pay Hari regularly. Hari decides to learn, and trust has changed him.","the lesson")],
 ("Anil gives Hari a fifty-rupee note on a day. How much will he pay in a 30-day month if he pays daily?",[("Multiply daily pay by days.","50 x 30."),("= 1,500 rupees.","The story only mentions the first payment; this is practice.")]),
 ("How did trust change Hari Singh?",["Anil trusted him","He returned the money","He chose to learn to read and write"],["Thinking Anil punished Hari"]),
 ["Hari is a fifteen-year-old thief.","Anil trusts him and employs him.","Hari returns the money.","Trust can change a person."],
 [M("fp2-1",1,"Who is the narrator?","Hari Singh","Anil","The police","He is the thief."),
  tf("fp2-2",1,"Hari Singh returned the notes to Anil.",True,"He slipped them under the mattress."),
  M("fp2-3",2,"What did Hari want to learn?","To read and write","To wrestle","To cook","He wanted to be a clever man."),
  AR("fp2-4",2,"Hari found it hard to rob Anil.","Anil was a trusting person.","It is hard to rob a careless man."),
  short("fp2-5",2,"What was Anil's profession?",["writer","a writer","struggling writer"],"He was a struggling writer.",[("wrestler","He only watched wrestling.")]),
  tf("fp2-6",3,"Hari planned to catch a train to Lucknow.",True,"The 10.30 Express."),
  M("fp2-7",3,"The theme of the story is","trust can change people","wrestling","travel","Anil's trust moved Hari."),
  M("fp2-8",3,"Ruskin Bond wrote","The Thief's Story","The Necklace","Bholi","This is his story.")])
L(3,"The Midnight Visitor",("A fat spy and a clever trick","Ausable is a secret agent who expects an important report. A gunman comes. Can Ausable outwit him?"),
 [("Fowler, a young writer who loves romance, visits Ausable in a gloomy French hotel. Ausable is fat and does not look like a spy.","Ausable and Fowler"),
  ("Ausable expects an important report at twelve-thirty and has a drink ordered for when he returns.","the report"),
  ("Another agent, Max, enters by the balcony with a gun and demands the report.","Max appears"),
  ("Max says he will wait with them for the thirty-one minutes until the appointment.","waiting"),
  ("Max says he will take the report when it arrives and also reveals he has a pass key. Then a knock is heard, and Ausable says it must be the police, whom he had asked to check on him.","the knock"),
  ("Max panics, says he will wait on the balcony, and climbs over the window sill with his gun still pointing at them.","Max climbs out"),
  ("Max drops and screams. The door opens and a waiter, Henry, brings the drink Ausable ordered. There were no police, and Ausable says there is no balcony.","no balcony"),
  ("The story shows presence of mind and courage. Quick thinking beats force.","presence of mind")],
 ("Ausable says the appointment is at twelve-thirty and Max arrives with 31 minutes left. At what time did Max arrive?",[("Subtract 31 minutes from 12:30.","12:30 - 0:31."),("= 11:59.","Practice only.")]),
 ("Explain how Ausable outwits Max.",["He invents the balcony story","Max drops from the window","The waiter's knock is a coincidence he uses"],["Thinking Ausable used a gun"]),
 ["Ausable is a fat, clever secret agent.","Max threatens him with a gun.","Ausable tricks Max with a balcony that does not exist.","The story shows presence of mind."],
 [M("fp3-1",1,"What kind of person is Ausable?","A fat, clever secret agent","A young soldier","A police officer","He does not look like a spy."),
  tf("fp3-2",1,"The balcony of Ausable's room actually existed.",False,"Ausable says there is no balcony."),
  M("fp3-3",2,"Who is Fowler?","A young writer who visits Ausable","A police officer","A waiter","He wants adventure."),
  AR("fp3-4",2,"Max fell.","He believed the balcony story.","Ausable tricked him."),
  short("fp3-5",2,"Who brought the drink at the end?",["a waiter","waiter","henry"],"A waiter named Henry came with the tray.",[("police","There were no police.")]),
  tf("fp3-6",3,"The story is by Robert Arthur.",True,"It is a mystery story."),
  M("fp3-7",3,"What does the story praise?","Presence of mind","Strength","Wealth","Ausable used quick thinking."),
  M("fp3-8",3,"The story's setting is","a French hotel","a village","a ship","The room was on the sixth floor.")])
L(4,"A Question of Trust",("The honest thief","Horace Danby is a respectable man who steals once a year. This year he is in for a surprise."),
 [("Horace Danby is about fifty, unmarried, a lock maker, and looks respectable. He is good but not completely honest.","Horace Danby"),
  ("He loves to collect rare books, and once a year he steals to buy them.","why he steals"),
  ("This year he plans to rob a wealthy house to get money for a special book.","the plan"),
  ("He opens the safe hidden behind a painting. His hay fever makes him sneeze with flowers around.","hay fever"),
  ("A young woman appears and surprises him. She says her jewels are in the safe and she has forgotten the combination.","the lady"),
  ("Horace is pleased to help, believing she is the lady of the house. He opens the safe and gives her the jewels.","he helps her"),
  ("Two days later the police arrest Horace. The woman had been a thief who stole the jewels, leaving his fingerprints behind.","the twist"),
  ("The story shows that even a careful planner can be fooled. Trust can be a trap.","moral")],
 ("Horace steals once a year for 15 years. How many robberies?",[("Count the years.","15 years, one a year."),("= 15 robberies.","The text says fifteen years ago he began.")]),
 ("Why was Horace deceived?",["He trusted the lady","He did not check her story","His planning left a gap"],["Thinking Horace was a hardened criminal"]),
 ["Horace Danby collects rare books and steals once a year.","He is tricked by a young woman.","She is the real thief.","The story shows trust and deceit."],
 [M("fp4-1",1,"What does Horace Danby collect?","Rare books","Stamps","Coins","He steals to buy them."),
  tf("fp4-2",1,"Horace Danby makes locks.",True,"He has two helpers."),
  M("fp4-3",2,"What illness troubled Horace?","Hay fever","Fever","Toothache","He sneezed among flowers."),
  AR("fp4-4",2,"Horace helped the lady open the safe.","He believed she was the lady of the house.","She claimed to have forgotten the numbers."),
  short("fp4-5",2,"Who is the real culprit?",["the young woman","the lady","woman","young woman"],"She took the jewels and tricked Horace.",[("horace","He was the victim of the trick, though he was also a thief.")]),
  tf("fp4-6",3,"Horace is a typical hardened thief.",False,"He is respectable but not fully honest."),
  M("fp4-7",3,"The title 'A Question of Trust' refers to","trusting a stranger","a bank","a book","He trusted the lady."),
  M("fp4-8",3,"The author of the story is","Victor Canning","Ruskin Bond","H. G. Wells","He wrote this tale.")])
L(5,"Footprints without Feet",("The man you cannot see","What would happen if a man could become invisible? H. G. Wells imagines it."),
 [("Two boys see fresh muddy footprints of bare feet appear with no one there. They follow the prints.","mysterious footprints"),
  ("The invisible man is Griffin, a scientist who found how to make himself invisible and tried it on himself.","Griffin"),
  ("He wanders cold and hungry in London, and finds that being invisible brings problems.","problems of being invisible"),
  ("He goes to a theatrical shop and puts on bandages, dark glasses, a false nose and a hat. He also robs the shopkeeper.","a disguise"),
  ("He takes a train to the village of Iping and rents two rooms at an inn. People find the stranger odd.","at Iping"),
  ("Strange things happen at the inn: a chair moves and a burglary at the clergyman's house is blamed on him.","strange events"),
  ("When Mrs Hall questions him, he loses his temper, throws off his bandages and nose, and shows he is invisible.","the reveal"),
  ("The story shows how a scientist can misuse a discovery, and makes us think about invisibility.","misuse of science")],
 ("Griffin rented 2 rooms for 5 nights. How many room-nights?",[("Multiply rooms by nights.","2 x 5."),("= 10 room-nights.","Practice only.")]),
 ("Is Griffin a good scientist or a misuser of science?",["He invented invisibility","He used it for theft","Science needs responsibility"],["Thinking invisibility is harmless"]),
 ["Griffin is an invisible scientist.","He wears a disguise.","He causes trouble at Iping.","Science must be used responsibly."],
 [M("fp5-1",1,"Who is the invisible man?","Griffin","Mrs Hall","Herriot","He is the scientist."),
  tf("fp5-2",1,"The boys saw footprints with no one visible.",True,"That is how the story starts."),
  M("fp5-3",2,"Where did he go to find clothes?","A theatrical shop in Drury Lane","A bakery","A school","He needed a disguise."),
  AR("fp5-4",2,"Mrs Hall questioned the scientist.","She was puzzled by the strange events at her inn.","He appeared out of an empty room."),
  short("fp5-5",2,"Which village did Griffin travel to?",["iping"],"He took a room at the inn.",[("london","He left London.")]),
  tf("fp5-6",3,"The story is by H. G. Wells.",True,"He wrote The Invisible Man."),
  M("fp5-7",3,"The story warns about","misuse of science","farming","cooking","Griffin used his discovery badly."),
  M("fp5-8",3,"What does Griffin wear on his face as disguise?","A false nose and dark glasses","A mask of gold","A crown","He tries to hide the empty space.")])
L(6,"The Making of a Scientist",("A boy and his butterflies","How did Richard Ebright become a scientist? A boy collecting butterflies and a mother who helped."),
 [("The piece is by Robert W. Peterson about Richard Ebright, a boy who loved butterflies.","Ebright"),
  ("As a child Ebright collected butterflies and learned their names. His mother encouraged his interest.","a young collector"),
  ("His mother gave him a book called The Travels of Monarch X, about monarch butterflies' migration to Central America.","the book"),
  ("The book invited readers to help tag butterflies for research by Dr Urquhart of the University of Toronto, and Ebright joined.","tagging butterflies"),
  ("He was a straight-A student and also took part in debating and the Model United Nations.","school life"),
  ("His social studies teacher, Mr Weiherer, opened his mind to new ideas and admired his hard work.","a good teacher"),
  ("Ebright was competitive, but he wanted to do the best job, not win just for a prize.","motivation"),
  ("The ingredients of a scientist include curiosity, parents' support, a good teacher and hard work.","ingredients")],
 ("Ebright studied for 3 hours each night for 5 nights. How many hours?",[("Multiply hours by nights.","3 x 5."),("= 15 hours.","The teacher said three or four hours; practice only.")]),
 ("List what made Ebright a scientist.",["Curiosity about butterflies","Mother's help","Teacher's encouragement and effort"],["Thinking only talent is needed"]),
 ["Ebright loved butterflies.","His mother and teacher helped him.","He joined a research project.","Curiosity and effort make a scientist."],
 [M("fp6-1",1,"What did Ebright collect?","Butterflies","Stamps","Coins","He loved them."),
  tf("fp6-2",1,"The Travels of Monarch X was a book about monarch migration.",True,"It opened science to him."),
  M("fp6-3",2,"Who was his admired teacher?","Mr Weiherer","Dr Urquhart","Mr Keesing","He taught social studies."),
  AR("fp6-4",2,"Ebright joined the tagging project.","The book invited readers to help.","His mother wrote to Dr Urquhart."),
  short("fp6-5",2,"Where did monarch butterflies migrate to, according to the book?",["central america"],"The book described their journey.",[("canada","Dr Urquhart's university is in Toronto.")]),
  tf("fp6-6",3,"Ebright was competitive only to win prizes.",False,"He wanted to do the best job."),
  M("fp6-7",3,"An ingredient of a scientist is","curiosity","laziness","fear","It is shown by his story."),
  M("fp6-8",3,"The article is written by","Robert W. Peterson","Ruskin Bond","Claire Boiko","He wrote about Ebright.")])
L(7,"The Necklace",("A borrowed jewel and a lost life","A woman wants to look rich for one night. What does it cost her?"),
 [("The story is by Guy de Maupassant. Matilda Loisel is pretty but unhappy with her modest life as a clerk's wife.","Mme Loisel"),
  ("Her husband brings an invitation to a ball. She is upset because she has no dress, so he gives her four hundred francs that he had saved for a gun.","the dress"),
  ("She is still sad for lack of a jewel, so she borrows a diamond necklace from her rich friend Mme Forestier.","the necklace"),
  ("At the ball she is a great success, but loses the necklace on the way home.","the loss"),
  ("They could not find it, so they bought a similar necklace and gave it back, going into heavy debt.","the replacement"),
  ("To repay, they worked hard for ten years, giving up their servant and home comforts, and she became rough and old.","ten years of labour"),
  ("One day she meets Mme Forestier and tells her the truth. Mme Forestier says the original was only imitation, worth very little.","the twist"),
  ("The story shows that pride and vanity can bring ruin, and honesty could have saved them.","moral")],
 ("The dress cost four hundred francs. If the clerk had saved 1,000 francs, how much is left?",[("Subtract the cost.","1000 - 400."),("= 600 francs.","Practice only.")]),
 ("What does the story teach about vanity and honesty?",["Vanity led to the loss","They paid for ten years","Honesty could have helped"],["Thinking the necklace was real"]),
 ["Mme Loisel borrowed a necklace and lost it.","They replaced it and paid ten years.","The original was imitation.","Vanity brings ruin; honesty helps."],
 [M("fp7-1",1,"From whom did Mme Loisel borrow the necklace?","Mme Forestier","Her mother","The jeweller","A rich friend."),
  tf("fp7-2",1,"The husband gave four hundred francs for a dress.",True,"He had saved the sum for a gun."),
  M("fp7-3",2,"Where did she lose the necklace?","On the way home from the ball","At the shop","At school","They could not find it."),
  AR("fp7-4",2,"The Loisels worked for ten years.","They had to repay a debt for the replacement.","They had given up comforts."),
  short("fp7-5",2,"Who wrote The Necklace?",["maupassant","guy de maupassant"],"He is a French writer.",[("ruskin bond","Bond wrote The Thief's Story.")]),
  tf("fp7-6",3,"The original necklace was real diamond.",False,"It was an imitation."),
  M("fp7-7",3,"The moral of the story is","vanity can be costly","money is everything","friends are bad","Pride made them lose years."),
  M("fp7-8",3,"What did Mme Loisel lack that she wanted?","A jewel to wear","A house","A friend","She borrowed one.")])
L(8,"Bholi",("From a slow girl to a strong woman","A little girl is called Bholi, a simpleton. A teacher changes her life."),
 [("The story is by K. A. Abbas. Bholi's real name is Sulekha, the youngest of Ramlal's children, and she is slow and has a stammer after an illness.","Sulekha"),
  ("At home she is ignored and treated as a burden, wearing her sisters' old clothes.","neglect at home"),
  ("When the school opens, Ramlal takes her there to be admitted, since no one wants to marry such a girl.","going to school"),
  ("Her kind teacher encourages her and treats her with love. Bholi slowly gains confidence and learns to speak.","the teacher's love"),
  ("Years later a well-to-do grocer, Bishamber Nath, who is older and limps, offers to marry her without asking for dowry, and her parents agree.","the marriage"),
  ("At the wedding Bholi, who had been willing for the sake of her family's honour, refuses to marry a man she calls mean, greedy and a coward.","Bholi says no"),
  ("She says she will teach in the school where she learnt so much and serve her parents.","her decision"),
  ("The story shows the power of education to give confidence and courage, especially to girls.","message")],
 ("Bholi is the youngest of 4 sisters. If she is 10 and each sister is 2 years older than the next, how old is the eldest?",[("Add 2 years for each of the three older sisters.","3 x 2 = 6."),("10 + 6 = 16 years for the eldest.","Practice only.")]),
 ("How did education change Bholi?",["Teacher's care","Learning to speak","Courage to refuse the marriage"],["Thinking Bholi was slow by nature"]),
 ["Bholi was called a simpleton.","Her teacher gave her confidence.","She refused an unfair marriage.","Education empowers."],
 [M("fp8-1",1,"What was Bholi's real name?","Sulekha","Champa","Radha","Bholi was a nickname."),
  tf("fp8-2",1,"Bholi was sent to school.",True,"Ramlal took her there."),
  M("fp8-3",2,"What did Bholi say to her father?","She would serve them and teach in the school","She would marry the grocer","She would leave home","She stayed calm and steady."),
  AR("fp8-4",2,"Bholi refused the marriage.","She had gained courage through education.","She saw her parents' greed."),
  short("fp8-5",2,"Who was the lame grocer?",["bishamber nath"],"Bishamber Nath, who offered to marry her.",[("ramlal","Ramlal is her father.")]),
  tf("fp8-6",3,"The writer of Bholi is K. A. Abbas.",True,"He wrote it."),
  M("fp8-7",3,"The story's message is","education gives courage","wealth is everything","greed is good","She changed through learning."),
  M("fp8-8",3,"The teacher is compared to","an artist completing a masterpiece","a judge","a soldier","The story ends with this image.")])
